    googleStatus = await requestCalendar('calendar.google.status');
    if (!(options && options.preserveNotice)) clearSyncNotice();
    if (googleStatus && googleStatus.connected && options && options.loadCalendars) {
      await refreshGoogleCalendars({ preserveNotice: true });
    }
