    row.addEventListener('click', () => openEventDialog(event.date, event.id));
    row.addEventListener('contextmenu', (domEvent) => openContextMenu(domEvent, { date: event.date, eventId: event.id }));
    const date = document.createElement('span');
    date.className = 'agenda-date';
    date.textContent = eventDateLabel(event);
    const main = document.createElement('span');
    main.className = 'agenda-main';
    const name = document.createElement('strong');
    name.textContent = event.title;
    const meta = document.createElement('span');
    meta.textContent = [event.time || '종일', event.type || '일정', event.location].filter(Boolean).join(' · ');
    main.append(name, meta, eventBadgeLine(event));
