  const id = document.getElementById('event-id').value || 'event-' + Date.now();
  const existing = events.find((candidate) => candidate.id === id);
  if (existing && guardOwnership(existing, '수정')) return;
  const title = document.getElementById('event-title').value.trim();
  const date = document.getElementById('event-date').value || selectedDate || toDateInput(today);
  if (!title) {
    document.getElementById('event-title').focus();
    return;
  }
  const allDay = document.getElementById('event-all-day').checked;
  const nextEvent = normalizeStoredEvent({
    id,
    title,
    date,
    time: allDay ? '' : document.getElementById('event-time').value,
    endTime: allDay ? '' : document.getElementById('event-end-time').value,
    type: document.getElementById('event-type').value,
    location: document.getElementById('event-location').value,
    notes: document.getElementById('event-notes').value,
    googleEventId: existing ? existing.googleEventId : '',
    googleCalendarId: existing ? existing.googleCalendarId : '',
    googleCalendarSummary: existing ? existing.googleCalendarSummary : '',
    googleICalUID: existing ? existing.googleICalUID : '',
    googleRecurringEventId: existing ? existing.googleRecurringEventId : '',
    googleOriginalStartTime: existing ? existing.googleOriginalStartTime : undefined,
    googleLinks: existing ? existing.googleLinks : [],
    updatedAt: Date.now()
  });
  events = events.some((candidate) => candidate.id === id)
    ? events.map((candidate) => candidate.id === id ? nextEvent : candidate)
    : [...events, nextEvent];
