  const result = await requestNoteAttachment('notes.attachment.saveClipboardImage');
  if (!result) return setFileStatus('클립보드 이미지 없음');
  const attachment = upsertAttachment(result);
  if (attachment) insertAttachmentMarkdown(attachment);
