  for (const item of menu.querySelectorAll('[data-children-only]')) item.hidden = !note || childNotes(note.id).length === 0;
  for (const item of menu.querySelectorAll('[data-parent-only]')) item.hidden = !note || !parentIdOf(note);
  for (const item of menu.querySelectorAll('[data-md-only]')) item.hidden = !note || !isMarkdownNote(note);
  for (const item of menu.querySelectorAll('[data-txt-only]')) item.hidden = !note || isMarkdownNote(note);
