async function requestIntegration(op, input) {
  return window.sepilotApps.request(op, input || {});
}
function recordValue(record, keys) {
  if (!record || typeof record !== 'object' || Array.isArray(record)) return '';
  for (const key of keys) {
    const value = record[key];
    if (typeof value === 'string' && value.trim()) return value.trim();
  }
  return '';
}
function messageReference(message) {
  const metadata = message && typeof message.metadata === 'object' && !Array.isArray(message.metadata) ? message.metadata : {};
  return recordValue(metadata, ['url', 'html_url', 'htmlUrl', 'link', 'permalink']) || recordValue(message, ['url', 'link']);
}
function messageTitle(message, index) {
  return recordValue(message, ['title', 'subject']) || '수신 메시지 ' + String(index + 1);
}
function messageBody(message) {
  return recordValue(message, ['body', 'content']) || '';
}
function messageSummary(message) {
  const body = messageBody(message).replace(/\\s+/g, ' ').trim();
  return body.length > 120 ? body.slice(0, 117) + '...' : body;
}
function sourceFromMessage(message) {
  const source = recordValue(message, ['source']);
  if (/github/i.test(source) || message.type === 'github_webhook') return 'GitHub';
  if (/gmail|mail/i.test(source)) return '메일';
  if (/file|folder|local/i.test(source)) return '로컬 파일';
  return source || '메시지';
}
function inboxItemFromMessage(message, index) {
  const hash = recordValue(message, ['hash', 'id']) || String(Date.now()) + '-' + index;
  const timestamp = Number(message.timestamp || message.queuedAt || Date.now());
  return normalizeItem({
    id: 'message-' + hash,
    source: sourceFromMessage(message),
    sender: recordValue(message, ['source']) || sourceFromMessage(message),
    subject: messageTitle(message, index),
    body: messageBody(message),
    receivedAt: toDateTimeInput(new Date(timestamp)),
    priority: message.type === 'github_webhook' ? 'P2' : 'P3',
    status: 'new',
    reference: messageReference(message),
    summary: messageSummary(message),
    createdAt: Date.now(),
    updatedAt: Date.now()
  }, index);
}
function localFileBody(file) {
  return recordValue(file, ['body', 'content', 'text', 'original']);
}
function localFileTitle(file, index) {
  return recordValue(file, ['subject', 'title']) || recordValue(file, ['name']) || '로컬 항목 ' + String(index + 1);
}
function localFileBaseName(value) {
  const text = String(value || '').split('\\\\').join('/');
  const parts = text.split('/').filter(Boolean);
  return parts.length > 0 ? parts[parts.length - 1] : '';
}
function isLocalAdapterHelperItem(item) {
  const name = (localFileBaseName(item && item.reference) || localFileBaseName(item && item.subject)).toLowerCase();
  return [
    'adapter.py',
    'adapter.js',
    'adapter.ts',
    'adapter.mjs',
    'adapter.cjs',
    'inbox-adapter.py',
    'inbox-adapter.js',
    'local-adapter.py',
    'local-adapter.js'
  ].includes(name);
}
function localFileReceivedAt(file) {
  const receivedAt = recordValue(file, ['receivedAt', 'received_at', 'date']);
  if (receivedAt) return receivedAt;
  const timestamp = Number(file.mtimeMs || file.timestamp || file.createdAt || Date.now());
  return toDateTimeInput(new Date(timestamp));
}
function inboxItemFromLocalFile(file, index) {
  const row = file && typeof file === 'object' && !Array.isArray(file) ? file : {};
  const reference = recordValue(row, ['reference', 'url', 'link', 'path']);
  const hash = recordValue(row, ['id', 'hash', 'externalKey']) || reference || String(Date.now()) + '-' + index;
  const body = localFileBody(row);
  const summary = recordValue(row, ['summary']) || body.replace(/\\s+/g, ' ').trim();
  return normalizeItem({
    id: 'local-adapter-' + hash,
    source: recordValue(row, ['source']) || '로컬 파일',
    sender: recordValue(row, ['sender', 'from', 'author', 'directoryName']) || '로컬 폴더',
    subject: localFileTitle(row, index),
    body,
    receivedAt: localFileReceivedAt(row),
    priority: recordValue(row, ['priority']) || 'P3',
    status: recordValue(row, ['status']) || 'new',
    reference,
    summary: summary.length > 120 ? summary.slice(0, 117) + '...' : summary,
    createdAt: Date.now(),
    updatedAt: Date.now()
  }, index);
}
async function loadMessageSubscription() {
  integrationBusy = true;
  renderIntegrationSettings();
  try {
    messageSubscriptionOverview = await requestIntegration('messageSubscription.overview');
    messageSubscriptionItems = await requestIntegration('messageSubscription.list', { limit: 30 });
    setSettingsMessage('메시지 구독 상태를 불러왔습니다.', false);
  } catch (error) {
    setSettingsMessage(error && error.message ? error.message : '메시지 구독을 확인할 수 없습니다.', true);
  } finally {
    integrationBusy = false;
    renderIntegrationSettings();
  }
}
