async function scanLocalFolder() {
  if (!integrations.localFolderPath) {
    setSettingsMessage('먼저 로컬 폴더를 선택하세요.', true);
    return;
  }
  if (!integrations.localAdapterCode || !integrations.localAdapterCode.trim()) {
    setSettingsMessage('로컬 폴더 adapter를 먼저 등록하세요.', true);
    return;
  }
  integrationBusy = true;
  renderIntegrationSettings();
  try {
    const result = await requestIntegration('localInbox.scanFolder', { path: integrations.localFolderPath, adapterCode: integrations.localAdapterCode });
    localFolderItems = result && Array.isArray(result.items) ? result.items : [];
    const importResult = importLocalFolderItems({ silent: true, returnStats: true });
    const importedCount = importResult.count;
    const scannedCount = result && typeof result.filesScanned === 'number' ? result.filesScanned : localFolderItems.length;
    if (importResult.stats && importResult.stats.error) {
      setSettingsMessage(importResult.stats.error, true);
    } else {
      setSettingsMessage('파일 ' + scannedCount + '개를 읽고 ' + importedCount + '건을 인박스로 동기화했습니다.' + filterStatsText(importResult.stats), false);
    }
  } catch (error) {
    setSettingsMessage(error && error.message ? error.message : '로컬 폴더 동기화에 실패했습니다.', true);
  } finally {
    integrationBusy = false;
    renderIntegrationSettings();
  }
}
function importLocalFolderItems(options) {
  const silent = Boolean(options && options.silent);
  const returnStats = Boolean(options && options.returnStats);
  const done = (count, stats) => returnStats ? { count, stats } : count;
  const incoming = Array.isArray(localFolderItems) ? localFolderItems : [];
  const candidates = incoming
    .map(inboxItemFromLocalFile)
    .filter((candidate) => !isLocalAdapterHelperItem(candidate))
    .filter((candidate) => !isDeletedInboxItem(candidate))
    .filter((candidate) => !items.some((item) => item.id === candidate.id || (candidate.reference && item.reference === candidate.reference)));
  const filtered = filterInboxCandidates(candidates);
  if (filtered.stats.error) {
    if (!silent) setSettingsMessage(filtered.stats.error, true);
    return done(0, filtered.stats);
  }
  const imported = filtered.items;
  if (imported.length === 0) {
    if (!silent) setSettingsMessage('가져올 새 로컬 항목이 없습니다.' + filterStatsText(filtered.stats), false);
    return done(0, filtered.stats);
  }
  items = imported.concat(items);
  selectedId = imported[0].id;
  persist();
  render();
  if (!silent) setSettingsMessage(String(imported.length) + '건을 인박스로 가져왔습니다.' + filterStatsText(filtered.stats), false);
  return done(imported.length, filtered.stats);
}
function closeContextMenu() {
  const menu = document.getElementById('inbox-context-menu');
  if (menu) menu.hidden = true;
}
function openContextMenu(event, itemId) {
  event.preventDefault();
  const itemExists = itemId && items.some((item) => item.id === itemId);
  if (itemExists) selectedId = itemId;
  contextItemId = itemExists ? itemId : selectedId;
  persist();
  render();
  const menu = document.getElementById('inbox-context-menu');
  if (!menu) return;
  const hasItem = Boolean(contextItemId && items.some((item) => item.id === contextItemId));
  for (const node of menu.querySelectorAll('[data-requires-item]')) {
    node.hidden = !hasItem;
  }
  menu.hidden = false;
  const width = menu.offsetWidth || 190;
  const height = menu.offsetHeight || 260;
  const x = Math.min(event.clientX, Math.max(8, window.innerWidth - width - 8));
  const y = Math.min(event.clientY, Math.max(8, window.innerHeight - height - 8));
  menu.style.left = x + 'px';
  menu.style.top = y + 'px';
}
function handleContextAction(action) {
  closeContextMenu();
  if (action === 'manual') {
    openManualDialog();
    return;
  }
  if (action === 'settings') {
    openSettingsDialog();
    return;
  }
  if (contextItemId && items.some((item) => item.id === contextItemId)) selectedId = contextItemId;
  if (action === 'mark-new') setSelectedStatus('new');
  if (action === 'mark-triaged') setSelectedStatus('triaged');
  if (action === 'mark-waiting') setSelectedStatus('waiting');
  if (action === 'mark-done') setSelectedStatus('done');
  if (action === 'mark-archive') setSelectedStatus('archived');
  if (action === 'priority-p1') setSelectedPriority('P1');
  if (action === 'priority-p2') setSelectedPriority('P2');
  if (action === 'copy-original') void copyOriginal();
  if (action === 'copy-markdown') void copyMarkdown();
  if (action === 'delete') deleteItem();
}
