    '<defs><marker id="seqArrow" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto"><path d="M0,0 L0,6 L9,3 z" fill="#0f766e"/></marker></defs>',
    '<rect width="100%" height="100%" rx="12" fill="#f8fafc"/>'
