    svg.push('<rect x="' + ((x1 + x2) / 2 - 72) + '" y="' + (y - 25) + '" width="144" height="20" rx="5" fill="#ffffff" stroke="#d8dee8"/>');
    svg.push('<text x="' + ((x1 + x2) / 2) + '" y="' + (y - 10) + '" text-anchor="middle" font-size="11" fill="#334155">' + escapeXml(message.text).slice(0, 52) + '</text>');
