  svg.push('<rect width="100%" height="100%" rx="12" fill="#f8fafc"/>');
  svg.push('<rect x="28" y="28" width="' + (width - 56) + '" height="' + (height - 56) + '" rx="10" fill="#ffffff" stroke="#d8dee8"/>');
  svg.push('<text x="48" y="58" font-size="13" font-weight="800" fill="#0f172a">' + escapeXml(message || 'Mermaid 원문 미리보기') + '</text>');
