  setMetric('metric-lines', diagram ? lineCount(diagram.code) : 0);
  setMetric('metric-prompts', diagram ? promptsFor(diagram.id).length : 0);
  setMetric('metric-issues', diagram ? validateDiagram(diagram).length : 0);
  setMetric('metric-tags', diagram && diagram.tags ? diagram.tags.split(',').map((tag) => tag.trim()).filter(Boolean).slice(0, 2).join(', ') || '태그 없음' : '태그 없음');
