  if (!split || window.matchMedia('(max-width: 920px)').matches) return;
  const rect = split.getBoundingClientRect();
  const available = splitAvailableWidth();
  const minPercent = (SOURCE_PANE_MIN_PX / available) * 100;
  const maxPercent = 100 - (PREVIEW_PANE_MIN_PX / available) * 100;
  if (minPercent >= maxPercent) return;
