  document.getElementById('editor-id').value = card.id;
  document.getElementById('editor-title').value = card.title || '';
  document.getElementById('editor-owner').value = card.owner || '';
  document.getElementById('editor-body').value = card.body || '';
  document.getElementById('editor-lane').value = laneById(card.laneId).id;
  const integrationNode = document.getElementById('editor-integration');
