  const index = order.findIndex((note) => note.id === id);
  if (index < 0) return;
  const note = order.splice(index, 1)[0];
  let target = index;
  if (action === 'front') target = order.length;
  if (action === 'forward') target = Math.min(order.length, index + 1);
  if (action === 'backward') target = Math.max(0, index - 1);
  if (action === 'back') target = 0;
