  const categoryList = document.getElementById('settings-category-list');
  const lockedNote = document.getElementById('settings-category-locked');
  const addButton = document.getElementById('add-category');
  const addInput = document.getElementById('new-category-name');
  const autoLock = document.getElementById('auto-lock');
  const lockOnBlur = document.getElementById('lock-on-blur');
