document.getElementById('import-mode').addEventListener('change', () => invalidateImportDraft('가져오기 방식을 확인하세요.'));
document.getElementById('search').addEventListener('input', (event) => {
  searchQuery = event.target.value;
  render();
});
document.getElementById('category-filter').addEventListener('change', (event) => {
  categoryFilter = event.target.value || 'all';
  render();
});
document.getElementById('auto-lock').addEventListener('change', (event) => {
  settings = { ...settings, autoLockMinutes: Number(event.target.value) };
  persistSettings();
});
document.getElementById('lock-on-blur').addEventListener('change', (event) => {
  settings = { ...settings, lockOnBlur: Boolean(event.target.checked) };
  persistSettings();
});
document.getElementById('change-pass-toggle').addEventListener('click', toggleChangePassPanel);
document.getElementById('change-pass-backup-check').addEventListener('change', refreshChrome);
document.getElementById('change-pass-apply').addEventListener('click', changePassphrase);
document.getElementById('vault-settings-toggle').addEventListener('click', openVaultSettings);
document.getElementById('vault-settings-close').addEventListener('click', closeVaultSettings);
document.getElementById('vault-settings-backdrop').addEventListener('click', (event) => {
  if (event.target.id === 'vault-settings-backdrop') closeVaultSettings();
});
document.getElementById('add-category').addEventListener('click', addCategory);
document.getElementById('new-category-name').addEventListener('keydown', (event) => {
  if (event.key === 'Enter') addCategory();
});
document.getElementById('undo-delete').addEventListener('click', undoDelete);
document.getElementById('dismiss-delete').addEventListener('click', dismissUndoDelete);
document.getElementById('save-icon').innerHTML = icon('save');
document.getElementById('add-icon').innerHTML = icon('plus');
document.getElementById('export-icon').innerHTML = icon('download');
document.getElementById('export-file-icon').innerHTML = icon('fileDown');
document.getElementById('import-icon').innerHTML = icon('upload');
document.getElementById('import-file-icon').innerHTML = icon('fileUp');
document.getElementById('preview-icon').innerHTML = icon('check');
document.getElementById('change-pass-icon').innerHTML = icon('shield');
document.getElementById('change-pass-apply-icon').innerHTML = icon('shield');
document.getElementById('vault-settings-icon').innerHTML = icon('settings');
document.getElementById('undo-delete-icon').innerHTML = icon('undo');
document.getElementById('search-icon').innerHTML = icon('search');
document.getElementById('import-close').innerHTML = icon('x');
document.getElementById('vault-settings-close').innerHTML = icon('x');
document.getElementById('dismiss-delete').innerHTML = icon('x');
document.getElementById('pass-icon').innerHTML = icon('key');
document.addEventListener('pointerdown', activityPing, true);
document.addEventListener('keydown', activityPing, true);
document.addEventListener('keydown', (event) => {
  if (event.key === 'Escape' && settingsOpen) closeVaultSettings();
});
document.addEventListener('input', activityPing, true);
window.addEventListener('blur', () => {
  if (settings.lockOnBlur && unlocked && !busy && !autoSaveBusy) lockVault({ blur: true });
});
document.addEventListener('visibilitychange', () => {
  if (document.hidden && settings.lockOnBlur && unlocked && !busy && !autoSaveBusy) lockVault({ blur: true });
});
setStatus(hasVault() ? '잠김' : '첫 설정', hasVault() ? 'locked' : 'setup');
render();
