const storageExplorerDataSchema: SepilotAppDataSchema = {
  fields: {
    title: { type: 'string', label: '앱 제목' },
    view: { type: 'json', label: '탐색기 보기 상태' },
  },
}

const storageExplorerScript = `
const app = window.sepilotApps;
const view = app.data.get(['view']) || {};
let snapshot = null;
let selectedAppId = typeof view.selectedAppId === 'string' ? view.selectedAppId : '';
let selectedPath = typeof view.selectedPath === 'string' ? view.selectedPath : '';
let currentFile = null;
let loading = false;

const els = {
  search: document.getElementById('storage-search'),
  notice: document.getElementById('storage-notice'),
  rootPath: document.getElementById('root-path'),
  collectedAt: document.getElementById('collected-at'),
  appCount: document.getElementById('metric-apps'),
  fileCount: document.getElementById('metric-files'),
  byteCount: document.getElementById('metric-bytes'),
  invalidCount: document.getElementById('metric-invalid'),
  apps: document.getElementById('storage-apps'),
  files: document.getElementById('storage-files'),
  fileTitle: document.getElementById('file-title'),
  fileMeta: document.getElementById('file-meta'),
  filePath: document.getElementById('file-path'),
  editor: document.getElementById('file-editor'),
  save: document.getElementById('save-file'),
  revert: document.getElementById('revert-file'),
  exportApp: document.getElementById('export-app'),
  deleteApp: document.getElementById('delete-app'),
  copyPath: document.getElementById('copy-path'),
  backup: document.getElementById('export-backup'),
  refresh: document.getElementById('refresh-storage')
};

function text(value) {
  return String(value == null ? '' : value);
}

function setNotice(message, kind) {
  els.notice.textContent = message || '-';
  els.notice.dataset.kind = kind || 'idle';
}

function formatBytes(value) {
  const bytes = Number(value || 0);
  if (!Number.isFinite(bytes) || bytes <= 0) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB'];
  let size = bytes;
  let index = 0;
  while (size >= 1024 && index < units.length - 1) {
    size = size / 1024;
    index += 1;
  }
  return (Math.round(size * 10) / 10) + ' ' + units[index];
}

function formatDate(value) {
  const ts = Number(value || 0);
  if (!Number.isFinite(ts) || ts <= 0) return '-';
  try {
    return new Intl.DateTimeFormat('ko-KR', {
      dateStyle: 'short',
      timeStyle: 'short'
    }).format(new Date(ts));
  } catch (_) {
    return '-';
  }
}

function escapeHtml(value) {
  return text(value).replace(/[&<>"]/g, function (ch) {
    return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[ch] || ch;
  });
}

function query() {
  return text(els.search.value).trim().toLowerCase();
}

function normalizePath(value) {
  return text(value).replace(/\\\\/g, '/');
}

function saveView() {
  app.data.set(['view'], {
    query: text(els.search.value),
    selectedAppId: selectedAppId,
    selectedPath: selectedPath
  });
}

function allFiles() {
  if (!snapshot) return [];
  const ownerFiles = snapshot.apps.flatMap(function (owner) {
    return owner.files.map(function (file) {
      return Object.assign({}, file, { ownerTitle: owner.title, ownerStatus: owner.status });
    });
  });
  return ownerFiles.concat(snapshot.looseFiles || []);
}

function fileMatches(file, needle) {
  if (!needle) return true;
  return [
    file.name,
    file.relativePath,
    file.appTitle,
    file.appKind,
    file.fileKind,
    file.ownerTitle
  ].some(function (value) {
    return text(value).toLowerCase().indexOf(needle) >= 0;
  });
}

function appMatches(owner, needle) {
  if (!needle) return true;
  return [
    owner.title,
    owner.id,
    owner.kind,
    owner.status,
    owner.path
  ].some(function (value) {
    return text(value).toLowerCase().indexOf(needle) >= 0;
  }) || owner.files.some(function (file) {
    return fileMatches(file, needle);
  });
}

function selectedOwner() {
  if (!snapshot || !selectedAppId) return null;
  return snapshot.apps.find(function (owner) {
    return owner.id === selectedAppId;
  }) || null;
}

function selectedFileEntry() {
  if (!selectedPath) return null;
  return allFiles().find(function (file) {
    return file.relativePath === selectedPath;
  }) || null;
}

function renderMetrics() {
  if (!snapshot) {
    els.appCount.textContent = '0';
    els.fileCount.textContent = '0';
    els.byteCount.textContent = '0 B';
    els.invalidCount.textContent = '0';
    els.rootPath.textContent = '-';
    els.collectedAt.textContent = '-';
    return;
  }
  const files = allFiles();
  const bytes = files.reduce(function (sum, file) {
    return sum + Number(file.sizeBytes || 0);
  }, 0);
  els.appCount.textContent = String(snapshot.apps.length);
  els.fileCount.textContent = String(files.filter(function (file) { return file.nodeType === 'file'; }).length);
  els.byteCount.textContent = formatBytes(bytes);
  els.invalidCount.textContent = String((snapshot.diagnostics || []).filter(function (item) { return item.status === 'invalid'; }).length);
  els.rootPath.textContent = snapshot.rootPath || '-';
  els.collectedAt.textContent = formatDate(snapshot.collectedAt);
}

function appButton(owner) {
  const invalid = owner.status !== 'valid';
  const issues = owner.validation && Array.isArray(owner.validation.issues) ? owner.validation.issues.length : 0;
  const statusLabel = owner.status === 'valid' ? '정상' : (owner.status === 'invalid' ? '검증 오류' : '상태 미확인');
  const issueText = invalid && issues ? ' · 검증 이슈 ' + issues + '개' : '';
  return '<button type="button" class="storage-item app-item ' + (owner.id === selectedAppId ? 'selected' : '') + '" data-app-id="' + escapeHtml(owner.id) + '">' +
    '<span class="item-title">' + escapeHtml(owner.title) + '</span>' +
    '<span class="item-meta">' + escapeHtml(owner.kind) + ' · ' + owner.metrics.fileCount + ' files · ' + formatBytes(owner.metrics.totalBytes) + escapeHtml(issueText) + '</span>' +
    '<span class="status-chip ' + (invalid ? 'invalid' : 'valid') + '">' + escapeHtml(statusLabel) + '</span>' +
    '</button>';
}

function fileButton(file) {
  const disabled = file.nodeType !== 'file';
  const status = file.sensitive ? '민감' : (file.editable ? '편집' : (file.readable ? '읽기' : file.nodeType));
  return '<button type="button" class="storage-item file-item ' + (file.relativePath === selectedPath ? 'selected' : '') + '" data-path="' + escapeHtml(file.relativePath) + '"' + (disabled ? '' : '') + '>' +
    '<span class="item-title">' + escapeHtml(normalizePath(file.relativePath)) + '</span>' +
    '<span class="item-meta">' + escapeHtml(file.fileKind) + ' · ' + formatBytes(file.sizeBytes) + ' · ' + formatDate(file.updatedAt) + '</span>' +
    '<span class="status-chip ' + (file.sensitive ? 'sensitive' : '') + '">' + escapeHtml(status) + '</span>' +
    '</button>';
}

function renderApps() {
  const needle = query();
  const apps = snapshot ? snapshot.apps.filter(function (owner) { return appMatches(owner, needle); }) : [];
  els.apps.innerHTML = apps.length
    ? apps.map(appButton).join('')
    : '<div class="empty">표시할 앱이 없습니다.</div>';
  Array.from(els.apps.querySelectorAll('[data-app-id]')).forEach(function (button) {
    button.addEventListener('click', function () {
      selectedAppId = button.getAttribute('data-app-id') || '';
      selectedPath = '';
      currentFile = null;
      saveView();
      render();
    });
  });
}

function renderFiles() {
  const needle = query();
  const owner = selectedOwner();
  const files = owner ? owner.files : allFiles();
  const filtered = files.filter(function (file) { return fileMatches(file, needle); });
  els.files.innerHTML = filtered.length
    ? filtered.map(fileButton).join('')
    : '<div class="empty">표시할 파일이 없습니다.</div>';
  Array.from(els.files.querySelectorAll('[data-path]')).forEach(function (button) {
    button.addEventListener('click', function () {
      const nextPath = button.getAttribute('data-path') || '';
      void selectFile(nextPath);
    });
  });
}

function setFilePanel(entry, result) {
  if (!entry) {
    els.fileTitle.textContent = '파일';
    els.fileMeta.textContent = '-';
    els.filePath.textContent = '-';
    els.editor.value = '';
    els.editor.disabled = true;
    els.save.disabled = true;
    els.revert.disabled = true;
    els.copyPath.disabled = true;
    els.exportApp.disabled = !selectedOwner();
    els.deleteApp.disabled = !selectedOwner() || selectedAppId === app.appId;
    return;
  }
  els.fileTitle.textContent = entry.name;
  els.fileMeta.textContent = entry.fileKind + ' · ' + formatBytes(entry.sizeBytes) + ' · ' + (entry.editable ? '편집 가능' : (entry.readable ? '읽기 전용' : '미지원'));
  els.filePath.textContent = normalizePath(entry.relativePath);
  els.copyPath.disabled = false;
  els.exportApp.disabled = !entry.appId;
  els.deleteApp.disabled = !entry.appId || entry.appId === app.appId;
  els.editor.disabled = !entry.editable;
  els.save.disabled = !entry.editable || !result;
  els.revert.disabled = !entry.readable;
  if (result) {
    els.editor.value = result.content;
  } else if (!entry.readable) {
    els.editor.value = '이 파일은 텍스트로 읽을 수 없습니다.';
  }
}

async function selectFile(path) {
  const entry = allFiles().find(function (file) {
    return file.relativePath === path;
  });
  selectedPath = entry ? entry.relativePath : '';
  selectedAppId = entry && entry.appId ? entry.appId : selectedAppId;
  currentFile = null;
  saveView();
  render();
  if (!entry) return;
  if (!entry.readable) {
    setFilePanel(entry, null);
    return;
  }
  try {
    setNotice('파일을 읽는 중...', 'busy');
    const result = await app.request('apps.storage.readFile', { relativePath: entry.relativePath });
    currentFile = result;
    setFilePanel(entry, result);
    setNotice('파일을 읽었습니다.', 'ok');
  } catch (error) {
    setNotice(error && error.message ? error.message : String(error), 'error');
  }
}

function renderFilePanel() {
  setFilePanel(selectedFileEntry(), currentFile);
}

function render() {
  renderMetrics();
  renderApps();
  renderFiles();
  renderFilePanel();
}

async function loadSnapshot() {
  if (loading) return;
  loading = true;
  els.refresh.disabled = true;
  try {
    setNotice('스토리지 스냅샷을 불러오는 중...', 'busy');
    snapshot = await app.request('apps.storage.snapshot');
    if (!selectedAppId && snapshot.apps[0]) selectedAppId = snapshot.apps[0].id;
    render();
    if (selectedPath) {
      const path = selectedPath;
      selectedPath = '';
      await selectFile(path);
    } else {
      setNotice('스토리지 스냅샷을 불러왔습니다.', 'ok');
    }
  } catch (error) {
    setNotice(error && error.message ? error.message : String(error), 'error');
    render();
  } finally {
    loading = false;
    els.refresh.disabled = false;
  }
}

async function saveCurrentFile() {
  if (!currentFile || !currentFile.file || !currentFile.file.editable) return;
  try {
    setNotice('파일을 저장하는 중...', 'busy');
    const result = await app.request('apps.storage.writeFile', {
      relativePath: currentFile.file.relativePath,
      content: els.editor.value,
      expectedSha256: currentFile.sha256
    });
    currentFile = result;
    snapshot = result.snapshot || snapshot;
    render();
    setNotice('저장했습니다.', 'ok');
  } catch (error) {
    setNotice(error && error.message ? error.message : String(error), 'error');
  }
}

async function exportSelectedApp() {
  const owner = selectedOwner();
  const entry = selectedFileEntry();
  const id = owner ? owner.id : (entry && entry.appId ? entry.appId : '');
  if (!id) return;
  try {
    setNotice('앱을 내보내는 중...', 'busy');
    const result = await app.request('apps.storage.exportApp', { id: id });
    setNotice(result && result.path ? '내보낸 파일: ' + result.path : '앱을 내보냈습니다.', 'ok');
  } catch (error) {
    setNotice(error && error.message ? error.message : String(error), 'error');
  }
}

async function exportBackup() {
  try {
    setNotice('전체 백업을 만드는 중...', 'busy');
    const result = await app.request('apps.storage.exportBackup');
    setNotice(result && result.path ? '백업 파일: ' + result.path : '전체 백업을 만들었습니다.', 'ok');
  } catch (error) {
    setNotice(error && error.message ? error.message : String(error), 'error');
  }
}

async function deleteSelectedApp() {
  const owner = selectedOwner();
  if (!owner || owner.id === app.appId) return;
  const ok = window.confirm('앱 "' + owner.title + '"을 복구 가능한 휴지통으로 이동할까요?');
  if (!ok) return;
  try {
    setNotice('앱을 삭제하는 중...', 'busy');
    snapshot = await app.request('apps.storage.deleteApp', { id: owner.id });
    selectedAppId = snapshot.apps[0] ? snapshot.apps[0].id : '';
    selectedPath = '';
    currentFile = null;
    saveView();
    render();
    setNotice('앱을 휴지통으로 이동했습니다.', 'ok');
  } catch (error) {
    setNotice(error && error.message ? error.message : String(error), 'error');
  }
}

async function copyPath() {
  const value = selectedPath || (selectedOwner() ? selectedOwner().path : '');
  if (!value) return;
  try {
    await app.clipboard.writeText(value);
    setNotice('경로를 복사했습니다.', 'ok');
  } catch (error) {
    setNotice(error && error.message ? error.message : String(error), 'error');
  }
}

els.search.value = typeof view.query === 'string' ? view.query : '';
els.search.addEventListener('input', function () {
  saveView();
  render();
});
els.refresh.addEventListener('click', function () { void loadSnapshot(); });
els.save.addEventListener('click', function () { void saveCurrentFile(); });
els.revert.addEventListener('click', function () {
  if (currentFile && currentFile.file) void selectFile(currentFile.file.relativePath);
});
els.exportApp.addEventListener('click', function () { void exportSelectedApp(); });
els.backup.addEventListener('click', function () { void exportBackup(); });
els.deleteApp.addEventListener('click', function () { void deleteSelectedApp(); });
els.copyPath.addEventListener('click', function () { void copyPath(); });

render();
void loadSnapshot();
`

