let subs = (Array.isArray(storedSubsValue) ? subsCollection.list() : Array.isArray(seed.subs) ? seed.subs : defaultSubs).map(normalizeSub);
let aiTrackers = normalizeAiTrackers(data.get([stateKey, 'aiTrackers']) || seed.aiTrackers || defaultAiUsage);
