  document.getElementById('metric-budget').dataset.tone = budgetLeft >= 0 ? 'ok' : 'danger';
  document.getElementById('metric-ai').textContent = fmtMoney(aiMonthly, 'KRW');
  document.getElementById('metric-renewals').textContent = String(dueSoon);
