  const values = normalizeOptionList((options || []).concat(service[key] ? [service[key]] : []), options || []);
  values.forEach(function(option) {
    const node = document.createElement('option');
    node.value = option;
    node.textContent = option;
    select.append(node);
  });
  select.value = service[key] || values[0] || '';
  select.addEventListener('change', function() {
    updateService(service.id, { [key]: select.value }, true);
  });
  select.addEventListener('focus', function() { selectService(service.id, false); });
