          healthStatus: 'unknown',
          healthMessage: '',
          lastCheckedAt: null,
          tcpStatus: '',
          tcpLatencyMs: null,
          httpStatus: '',
          httpStatusCode: null,
          httpLatencyMs: null,
          history: []
