          criticality: { type: 'string', label: '중요도' },
          category: { type: 'string', label: '카탈로그' },
          tags: { type: 'string', label: '태그' },
          runbook: { type: 'string', label: '런북' },
          notes: { type: 'string', label: '메모' },
          port: { type: 'number', label: 'TCP 포트' },
          expectedStatus: { type: 'string', label: '기대 응답' },
          sloTarget: { type: 'number', label: 'SLO 목표' },
          sloWindowDays: { type: 'number', label: 'SLO 기간' },
          checkIntervalMinutes: { type: 'number', label: '체크 주기' },
          oncall: { type: 'string', label: '온콜/채널' },
