          lastCheckedAt: { type: 'number', label: '마지막 체크 시각' },
          tcpStatus: { type: 'string', label: 'TCP 상태' },
          tcpLatencyMs: { type: 'number', label: 'TCP 응답 ms' },
          httpStatus: { type: 'string', label: 'HTTP 상태' },
