  if (connection.credentialType) requestConnection.credentialType = connection.credentialType;
  if (connection.rancherSourceId) requestConnection.rancherSourceId = connection.rancherSourceId;
  if (connection.rancherUrl) requestConnection.rancherUrl = connection.rancherUrl;
  if (connection.rancherClusterId) requestConnection.rancherClusterId = connection.rancherClusterId;
  if (connection.rancherClusterName) requestConnection.rancherClusterName = connection.rancherClusterName;
