  const actions = make('div', 'row-actions');
  const edit = make('button', 'btn compact-action', '편집');
  edit.type = 'button';
  edit.addEventListener('click', function() { openClusterEditDialog(cluster); });
  const remove = make('button', 'btn danger compact-action', '삭제');
