const smarthomeScript = `
const data = window.sepilotApps.data;
const col = window.sepilotApps.collection('devices');
const ROOMS = ['거실', '주방', '침실', '현관', '서재', '베란다', '욕실', '기타'];
const TYPES = ['조명', '플러그', '센서', '에어컨', '난방', '스피커', 'CCTV', '도어락', '공기청정기', '커튼', '기타'];
const PROVIDERS = ['SmartThings', 'Google Home', 'Matter', 'Home Assistant', '수동'];
const SMART_TABS = [
  { id: 'power', label: '전력 소비 관리', note: '소비량 추적 · 전원 최적화' },
  { id: 'air', label: '공기질/온도 관리', note: '에어컨 · 공기청정기 · 센서' },
  { id: 'favorites', label: '즐겨찾기', note: '자주 쓰는 기기' },
  { id: 'devices', label: '전체 디바이스 관리', note: '방별 전체 목록' }
];
const POWER_TYPES = ['조명', '플러그', '스피커', 'CCTV', '커튼', '도어락'];
const AIR_TYPES = ['에어컨', '난방', '공기청정기', '센서'];
const STATUS_LABELS = { ON: '켜짐', OFF: '꺼짐', standby: '대기', offline: '오프라인', locked: '잠김', unlocked: '열림' };
const TYPE_META = {
  '조명': { icon: 'L', tone: 'light' },
  '플러그': { icon: 'P', tone: 'plug' },
  '센서': { icon: 'S', tone: 'sensor' },
  '에어컨': { icon: 'A', tone: 'climate' },
  '난방': { icon: 'H', tone: 'climate' },
  '스피커': { icon: 'M', tone: 'media' },
  'CCTV': { icon: 'C', tone: 'security' },
  '도어락': { icon: 'K', tone: 'security' },
  '공기청정기': { icon: 'F', tone: 'air' },
  '커튼': { icon: 'W', tone: 'shade' },
  '기타': { icon: 'I', tone: 'default' }
};
const stored = data.get(['collections', 'devices']);
const dashboardSeed = data.get(['smartHomeDashboard']) || {};
let devices = (Array.isArray(stored) ? col.list() : []).map(normalizeDevice);
let activeRoom = ROOMS.includes(dashboardSeed.activeRoom) || dashboardSeed.activeRoom === '전체' ? dashboardSeed.activeRoom : '전체';
let activeProvider = PROVIDERS.includes(dashboardSeed.activeProvider) ? dashboardSeed.activeProvider : '전체';
let sourceProvider = PROVIDERS.includes(dashboardSeed.sourceProvider) ? dashboardSeed.sourceProvider : 'SmartThings';
let activeSmartTab = SMART_TABS.some(function(tab) { return tab.id === dashboardSeed.activeTab; }) ? dashboardSeed.activeTab : 'devices';
let selectedId = dashboardSeed.selectedId || (devices[0] && devices[0].id) || '';
let searchQuery = '';
let syncMessage = typeof dashboardSeed.syncMessage === 'string' ? dashboardSeed.syncMessage : '로컬 패널';
let lastSyncAt = typeof dashboardSeed.lastSyncAt === 'number' ? dashboardSeed.lastSyncAt : null;
let integrationStatus = dashboardSeed.integrationStatus && typeof dashboardSeed.integrationStatus === 'object' ? dashboardSeed.integrationStatus : null;
let syncBusy = false;
let noticeTimer = 0;
const shouldPersist = !Array.isArray(stored);
if (!devices.some(function(device) { return device.id === selectedId; })) selectedId = (devices[0] && devices[0].id) || '';
if (devices.length === 0) activeRoom = '전체';

function text(value) { return value == null ? '' : String(value).trim(); }
function number(value, fallback) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}
function bool(value, fallback) {
  if (typeof value === 'boolean') return value;
  if (String(value).toUpperCase() === 'ON') return true;
  if (String(value).toUpperCase() === 'OFF') return false;
  return fallback;
}
function choice(options, value, fallback) {
  const raw = text(value);
  return options.includes(raw) ? raw : fallback;
}
function safeId(prefix) {
  return prefix + '-' + Date.now().toString(36) + '-' + Math.random().toString(16).slice(2, 7);
}
function legacyStatus(value, type, power) {
  const raw = text(value);
  const upper = raw.toUpperCase();
  if (type === '도어락') {
    if (raw === '잠김' || raw === 'locked' || raw === '대기') return 'locked';
    if (raw === '열림' || raw === 'unlocked') return 'unlocked';
  }
  if (upper === 'ON') return 'ON';
  if (upper === 'OFF') return 'OFF';
  if (raw === '오프라인') return 'offline';
  if (raw === '대기') return 'standby';
  return power ? 'ON' : 'OFF';
}
function providerFrom(value, brand) {
  const raw = text(value);
  if (PROVIDERS.includes(raw)) return raw;
  const brandText = text(brand).toLowerCase();
  if (brandText.includes('google')) return 'Google Home';
  if (brandText.includes('matter')) return 'Matter';
  if (brandText.includes('home assistant')) return 'Home Assistant';
  if (brandText.includes('smartthings') || brandText.includes('samsung')) return 'SmartThings';
  return raw || '수동';
}
function normalizeDevice(value, index) {
  const source = value && typeof value === 'object' ? value : {};
  const fallback = {};
  const type = choice(TYPES, source.type || fallback.type, '기타');
  const provider = providerFrom(source.provider, source.brand || fallback.brand);
  const power = bool(source.power, legacyStatus(source.status || fallback.status, type, true) === 'ON' || type === '도어락');
  const status = legacyStatus(source.status || fallback.status, type, power);
  const brightness = Math.max(1, Math.min(100, number(source.brightness, number(fallback.brightness, 70))));
  const targetTemp = Math.max(16, Math.min(32, number(source.targetTemp, number(fallback.targetTemp, 24))));
  return {
    id: text(source.id) || text(fallback.id) || safeId('devices'),
    name: text(source.name) || text(fallback.name) || '새 기기',
    room: choice(ROOMS, source.room || fallback.room, '기타'),
    type: type,
    provider: provider,
    brand: text(source.brand) || text(fallback.brand) || provider,
    externalId: text(source.externalId) || text(fallback.externalId),
    componentId: text(source.componentId) || text(fallback.componentId) || 'main',
    capabilities: Array.isArray(source.capabilities) ? source.capabilities.map(text).filter(Boolean) : (Array.isArray(fallback.capabilities) ? fallback.capabilities.map(text).filter(Boolean) : []),
    metadata: source.metadata && typeof source.metadata === 'object' ? source.metadata : (fallback.metadata && typeof fallback.metadata === 'object' ? fallback.metadata : {}),
    status: status,
    power: type === '센서' ? true : power,
    brightness: brightness,
    targetTemp: targetTemp,
    currentValue: number(source.currentValue, number(fallback.currentValue, type === '센서' ? 22 : 0)),
    unit: text(source.unit) || text(fallback.unit) || (type === '센서' ? '℃' : ''),
    battery: source.battery === null ? null : number(source.battery, fallback.battery == null ? null : number(fallback.battery, null)),
    mode: text(source.mode) || text(fallback.mode) || defaultMode(type),
    favorite: Boolean(source.favorite || fallback.favorite),
    lastSeen: number(source.lastSeen, number(fallback.lastSeen, Date.now())),
    notes: text(source.notes)
  };
}
function defaultMode(type) {
  if (type === '에어컨' || type === '난방' || type === '공기청정기') return '자동';
  if (type === '커튼') return '중간';
  return '';
}
function persist() {
  data.set(['collections', 'devices'], devices);
  data.set(['smartHomeDashboard'], {
    activeRoom: activeRoom,
    activeProvider: activeProvider,
    sourceProvider: sourceProvider,
    activeTab: activeSmartTab,
    selectedId: selectedId,
    syncMessage: syncMessage,
    lastSyncAt: lastSyncAt,
    integrationStatus: integrationStatus
  });
}
function create(tag, className, value) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (value != null) node.textContent = value;
  return node;
}
function byId(id) {
  return devices.find(function(device) { return device.id === id; }) || null;
}
function selectedDevice() {
  const selected = byId(selectedId);
  const rows = visibleDevices();
  if (selected && rows.some(function(device) { return device.id === selected.id; })) return selected;
  return rows[0] || null;
}
function isOnline(device) {
  return device.status !== 'offline';
}
function isPowerOn(device) {
  if (device.type === '도어락') return device.status === 'locked';
  return device.power && isOnline(device);
}
function needsAttention(device) {
  return !isOnline(device) || (device.battery != null && Number(device.battery) < 20) || device.status === 'unlocked';
}
function statusLabel(device) {
  if (device.type === '도어락') return STATUS_LABELS[device.status] || '잠김';
  if (device.type === '센서') return formatValue(device);
  return STATUS_LABELS[device.status] || (device.power ? '켜짐' : '꺼짐');
}
function formatValue(device) {
  const value = number(device.currentValue, 0);
  return (Math.round(value * 10) / 10).toString() + (device.unit || '');
}
function formatTime(timestamp) {
  if (!timestamp) return '아직 없음';
  return new Date(timestamp).toLocaleString('ko-KR', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
}
function fillSelect(select, options, value) {
  if (!select) return;
  select.replaceChildren();
  options.forEach(function(option) {
    const node = document.createElement('option');
    node.value = option;
    node.textContent = option;
    select.append(node);
  });
  select.value = options.includes(value) ? value : options[0];
}
function visibleDevices() {
  const query = searchQuery.toLowerCase();
  return tabDevices().filter(function(device) {
    if (activeSmartTab === 'devices' && activeRoom !== '전체' && device.room !== activeRoom) return false;
    if (activeProvider !== '전체' && device.provider !== activeProvider) return false;
    if (!query) return true;
    return [device.name, device.room, device.type, device.provider, device.brand, device.status, device.notes].join(' ').toLowerCase().includes(query);
  }).sort(function(a, b) {
    return Number(b.favorite) - Number(a.favorite) || a.room.localeCompare(b.room, 'ko-KR') || a.name.localeCompare(b.name, 'ko-KR');
  });
}
function tabDevicesFor(tabId) {
  if (tabId === 'power') return devices.filter(function(device) { return POWER_TYPES.includes(device.type); });
  if (tabId === 'air') return devices.filter(function(device) { return AIR_TYPES.includes(device.type); });
  if (tabId === 'favorites') return devices.filter(function(device) { return device.favorite; });
  return devices.slice();
}
function tabDevices() {
  return tabDevicesFor(activeSmartTab);
}
function tabCount(tabId) {
  return tabDevicesFor(tabId).length;
}
function estimatedWatts(device) {
  if (!isPowerOn(device)) return 0;
  if (device.type === '조명') return Math.max(4, Math.round(12 * number(device.brightness, 70) / 100));
  if (device.type === '플러그') return 38;
  if (device.type === '에어컨' || device.type === '난방') return 820;
  if (device.type === '공기청정기') return 34;
  if (device.type === '스피커') return 16;
  if (device.type === 'CCTV') return 8;
  if (device.type === '커튼') return 3;
  return 0;
}
function averageSensorValue() {
  const sensors = devices.filter(function(device) { return device.type === '센서' && device.unit === '℃'; });
  if (sensors.length === 0) return '-';
  const sum = sensors.reduce(function(total, device) { return total + number(device.currentValue, 0); }, 0);
  return Math.round(sum / sensors.length * 10) / 10 + '℃';
}
function modeTitle() {
  const tab = SMART_TABS.find(function(item) { return item.id === activeSmartTab; }) || SMART_TABS[3];
  return tab.label;
}
function setNotice(message, tone) {
  const node = document.getElementById('smart-notice');
  node.hidden = !message;
  node.textContent = message || '';
  node.dataset.tone = tone || '';
  window.clearTimeout(noticeTimer);
  if (message) {
    noticeTimer = window.setTimeout(function() { node.hidden = true; }, 2600);
  }
}
async function requestSmartHome(op, input) {
  if (!window.sepilotApps || typeof window.sepilotApps.request !== 'function') {
    throw new Error('Desktop Smart Home bridge is unavailable.');
  }
  return window.sepilotApps.request(op, input || {});
}
function providerStatus(provider) {
  if (!integrationStatus) return null;
  return provider === 'Google Home' ? integrationStatus.googleHome : integrationStatus.smartThings;
}
function brandLabel(device) {
  const brand = text(device.brand);
  return brand && brand !== device.provider ? brand : '';
}
function liveProvider(device) {
  return device.provider === 'SmartThings' || device.provider === 'Google Home';
}
function canControlDevice(device) {
  return device.provider === 'SmartThings' && Boolean(device.externalId);
}
function integrationLabel(provider) {
  const status = providerStatus(provider);
  if (!status) return '연동 상태 확인 전';
  if (provider === 'Google Home' && status.available === false) return status.configured ? '설정됨 · 데스크톱 제어 제한' : 'Google Home 설정 필요';
  return status.configured ? '연동 준비됨' : '설정 필요';
}
function displaySyncMessage(message) {
  const raw = text(message);
  if (!raw) return '로컬 패널';
  return raw.replace(/^(SmartThings|Google Home|Matter|Home Assistant|수동) +/, '');
}
function syncTone(message) {
  const raw = text(message);
  if (syncBusy) return 'busy';
  if (raw.includes('실패')) return 'error';
  if (raw.includes('필요')) return 'warn';
  if (raw.includes('완료') || raw.includes('준비')) return 'ok';
  return 'idle';
}
async function loadIntegrationStatus(showNotice) {
  try {
    integrationStatus = await requestSmartHome('smarthome.integrations.status');
    persist();
    renderMetrics();
    if (showNotice) setNotice('Smart Home 연동 상태를 확인했습니다.', 'ok');
  } catch (error) {
    if (showNotice) setNotice(error instanceof Error ? error.message : String(error), 'error');
  }
}
function mergeSyncedDevices(provider, syncedDevices) {
  const incoming = Array.isArray(syncedDevices) ? syncedDevices.map(normalizeDevice) : [];
  const syncedKeys = new Set(incoming.map(function(device) { return device.externalId || device.id; }));
  const local = devices.filter(function(device) {
    if (device.provider !== provider) return true;
    const key = device.externalId || device.id;
    return !syncedKeys.has(key) && !device.externalId;
  });
  devices = incoming.concat(local).map(normalizeDevice);
  if (!devices.some(function(device) { return device.id === selectedId; })) {
    selectedId = (devices[0] && devices[0].id) || '';
  }
}
async function sendDeviceCommand(device, action, value, patch) {
  const before = Object.assign({}, device);
  updateDevice(device.id, patch, true);
  if (!canControlDevice(device)) {
    if (device.provider === 'Google Home') setNotice('Google Home은 현재 데스크톱 직접 제어가 제한됩니다.', 'error');
    return;
  }
  try {
    const result = await requestSmartHome('smarthome.device.command', {
      provider: device.provider,
      deviceId: device.externalId,
      componentId: device.componentId || 'main',
      action: action,
      value: value,
      device: Object.assign({}, device, patch)
    });
    if (result && result.device) {
      updateDevice(device.id, result.device, true);
    } else {
      setNotice('SmartThings 명령을 전송했습니다.', 'ok');
    }
  } catch (error) {
    updateDevice(device.id, before, true);
    setNotice(error instanceof Error ? error.message : String(error), 'error');
  }
}
function renderMetrics() {
  const total = devices.length;
  const active = devices.filter(isPowerOn).length;
  const attention = devices.filter(needsAttention).length;
  const rooms = new Set(devices.map(function(device) { return device.room; })).size;
  document.getElementById('metric-total').textContent = String(total);
  document.getElementById('metric-active').textContent = String(active);
  document.getElementById('metric-attention').textContent = String(attention);
  document.getElementById('metric-rooms').textContent = String(rooms);
  document.getElementById('visible-count').textContent = String(visibleDevices().length);
  document.getElementById('source-provider').value = sourceProvider;
  document.getElementById('provider-filter').value = activeProvider;
  const syncButton = document.getElementById('sync-now');
  if (syncButton) {
    syncButton.disabled = syncBusy;
    syncButton.title = integrationLabel(sourceProvider);
  }
  const syncStatus = document.getElementById('sync-status');
  const syncCopy = document.getElementById('sync-copy');
  const fullSyncMessage = syncBusy ? sourceProvider + ' 동기화 중' : syncMessage;
  syncStatus.textContent = syncBusy ? '동기화 중' : displaySyncMessage(syncMessage);
  syncStatus.title = fullSyncMessage;
  if (syncCopy) syncCopy.dataset.tone = syncTone(fullSyncMessage);
  document.getElementById('last-sync').textContent = lastSyncAt ? formatTime(lastSyncAt) : '동기화 전';
}
function renderRibbonTabs() {
  const root = document.getElementById('smart-ribbon');
  root.replaceChildren();
  SMART_TABS.forEach(function(tab) {
    const button = create('button', 'ribbon-tab' + (tab.id === activeSmartTab ? ' active' : ''), '');
    button.type = 'button';
    button.dataset.smartTab = tab.id;
    button.append(create('strong', '', tab.label), create('span', '', tab.note), create('em', '', String(tabCount(tab.id))));
    button.addEventListener('click', function() {
      activeSmartTab = tab.id;
      if (activeSmartTab !== 'devices') activeRoom = '전체';
      const rows = visibleDevices();
      if (rows.length && !rows.some(function(device) { return device.id === selectedId; })) selectedId = rows[0].id;
      persist();
      render();
    });
    root.append(button);
  });
}
function summaryTile(label, value, note, tone) {
  const tile = create('article', 'summary-tile ' + (tone || ''), '');
  tile.append(create('span', '', label), create('strong', '', value), create('small', '', note));
  return tile;
}
function renderTabSummary() {
  const root = document.getElementById('tab-summary');
  root.replaceChildren();
  const scoped = tabDevicesFor(activeSmartTab);
  if (activeSmartTab === 'power') {
    const powered = scoped.filter(isPowerOn).length;
    const watts = scoped.reduce(function(total, device) { return total + estimatedWatts(device); }, 0);
    root.append(
      summaryTile('작동 중', String(powered) + '개', '전력 사용 기기', powered ? 'on' : ''),
      summaryTile('추정 부하', watts ? String(watts) + 'W' : '0W', '현재 상태 기준', watts > 600 ? 'warn' : ''),
      summaryTile('대기/꺼짐', String(scoped.length - powered) + '개', '원격 제어 가능 후보', ''),
      summaryTile('자동화 후보', String(scoped.filter(function(device) { return isPowerOn(device) && !device.favorite; }).length) + '개', '자주 쓰지 않는 작동 기기', 'accent')
    );
  } else if (activeSmartTab === 'air') {
    const climate = scoped.filter(function(device) { return device.type === '에어컨' || device.type === '난방' || device.type === '공기청정기'; });
    root.append(
      summaryTile('공조 장비', String(climate.length) + '개', '에어컨/난방/청정기', 'accent'),
      summaryTile('작동 중', String(climate.filter(isPowerOn).length) + '개', '현재 켜진 공조 장비', 'on'),
      summaryTile('평균 온도', averageSensorValue(), '온도 센서 기준', ''),
      summaryTile('확인 필요', String(scoped.filter(needsAttention).length) + '개', '배터리/오프라인 포함', scoped.some(needsAttention) ? 'warn' : '')
    );
  } else if (activeSmartTab === 'favorites') {
    root.append(
      summaryTile('즐겨찾기', String(scoped.length) + '개', '빠른 접근 기기', 'accent'),
      summaryTile('작동 중', String(scoped.filter(isPowerOn).length) + '개', '현재 켜짐/잠김', 'on'),
      summaryTile('장소', String(new Set(scoped.map(function(device) { return device.room; })).size) + '곳', '즐겨찾기 분포', ''),
      summaryTile('확인 필요', String(scoped.filter(needsAttention).length) + '개', '주의 상태', scoped.some(needsAttention) ? 'warn' : '')
    );
  } else {
    root.append(
      summaryTile('전체 기기', String(devices.length) + '개', '등록된 전체 디바이스', 'accent'),
      summaryTile('방 필터', activeRoom, '현재 목록 기준', ''),
      summaryTile('표시 중', String(visibleDevices().length) + '개', '검색/연동 필터 반영', ''),
      summaryTile('확인 필요', String(devices.filter(needsAttention).length) + '개', '오프라인/배터리/도어락', devices.some(needsAttention) ? 'warn' : '')
    );
  }
}
function renderRoomTabs() {
  const tabs = document.getElementById('room-tabs');
  tabs.replaceChildren();
  const rooms = ['전체'].concat(ROOMS.filter(function(room) {
    return devices.some(function(device) { return device.room === room; }) || room === activeRoom;
  }));
  rooms.forEach(function(room) {
    const count = room === '전체' ? devices.length : devices.filter(function(device) { return device.room === room; }).length;
    const button = create('button', 'room-tab' + (room === activeRoom ? ' active' : ''), '');
    button.type = 'button';
    button.dataset.room = room;
    button.append(create('strong', '', room), create('span', '', String(count)));
    button.addEventListener('click', function() {
      activeRoom = room;
      persist();
      render();
    });
    tabs.append(button);
  });
}
function updateDevice(id, patch, rerender) {
  devices = devices.map(function(device, index) {
    return device.id === id ? normalizeDevice(Object.assign({}, device, patch, { lastSeen: Date.now() }), index) : device;
  });
  persist();
  if (rerender) render();
  else renderMetrics();
}
function selectDevice(id, rerender) {
  selectedId = id;
  persist();
  if (rerender) render();
}
function closeDeviceMenu() {
  const menu = document.getElementById('device-context-menu');
  if (menu) menu.hidden = true;
}
function menuDivider() {
  return create('div', 'menu-separator');
}
function menuButton(label, handler, active) {
  const button = create('button', active ? 'active' : '', label);
  button.type = 'button';
  button.setAttribute('role', 'menuitem');
  button.addEventListener('click', function() {
    handler();
    closeDeviceMenu();
  });
  return button;
}
function positionDeviceMenu(menu, x, y) {
  menu.hidden = false;
  menu.style.left = '0px';
  menu.style.top = '0px';
  const rect = menu.getBoundingClientRect();
  const padding = 8;
  const left = Math.min(Math.max(padding, x), window.innerWidth - rect.width - padding);
  const top = Math.min(Math.max(padding, y), window.innerHeight - rect.height - padding);
  menu.style.left = left + 'px';
  menu.style.top = top + 'px';
}
function openDeviceMenu(event, id) {
  event.preventDefault();
  event.stopPropagation();
  const device = byId(id);
  if (!device) return;
  selectedId = id;
  persist();
  renderDetail();
  const menu = document.getElementById('device-context-menu');
  menu.replaceChildren();
  const head = create('div', 'device-menu-head');
  head.append(create('strong', '', device.name), create('span', '', device.room + ' · ' + device.type));
  menu.append(head, menuDivider(), create('span', 'device-menu-label', '방 이동'));
  ROOMS.forEach(function(room) {
    menu.append(menuButton((room === device.room ? '✓ ' : '') + room, function() {
      if (room !== device.room) updateDevice(id, { room: room }, true);
    }, room === device.room));
  });
  positionDeviceMenu(menu, event.clientX, event.clientY);
}
function powerPatch(device, checked) {
  if (device.type === '도어락') {
    return { power: checked, status: checked ? 'locked' : 'unlocked' };
  }
  return { power: checked, status: checked ? 'ON' : 'OFF' };
}
function iconFor(device) {
  return TYPE_META[device.type] || TYPE_META['기타'];
}
function renderCards() {
  const grid = document.getElementById('device-grid');
  grid.replaceChildren();
  const rows = visibleDevices();
  if (rows.length === 0) {
    const emptyText = activeSmartTab === 'power'
      ? '전력 소비 관리 대상 기기가 없습니다.'
      : activeSmartTab === 'air'
        ? '공기질/온도 관리 대상 기기가 없습니다.'
        : activeSmartTab === 'favorites'
          ? '즐겨찾기 기기가 없습니다.'
          : devices.length ? '조건에 맞는 기기가 없습니다.' : '등록된 기기가 없습니다.';
    grid.append(create('div', 'empty smart-empty', emptyText));
    return;
  }
  rows.forEach(function(device) {
    const meta = iconFor(device);
    const card = create('article', 'device-card ' + meta.tone + (isPowerOn(device) ? ' on' : ' off') + (needsAttention(device) ? ' attention' : '') + (device.id === selectedId ? ' selected' : ''));
    card.addEventListener('click', function(event) {
      if (event.target && ['INPUT', 'SELECT', 'BUTTON', 'TEXTAREA'].includes(event.target.tagName)) return;
      selectDevice(device.id, true);
    });
    card.addEventListener('contextmenu', function(event) { openDeviceMenu(event, device.id); });

    const head = create('div', 'device-head');
    const face = create('div', 'device-face ' + meta.tone, meta.icon);
    const title = create('div', 'device-title');
    const name = document.createElement('input');
    name.className = 'device-name';
    name.value = device.name;
    name.placeholder = '기기명';
    name.addEventListener('focus', function() { selectDevice(device.id, false); });
    name.addEventListener('input', function() { updateDevice(device.id, { name: name.value }, false); });
    const sub = create('span', '', device.room + ' · ' + device.type);
    title.append(name, sub);
    const fav = create('button', 'icon-action favorite' + (device.favorite ? ' active' : ''), device.favorite ? '★' : '☆');
    fav.type = 'button';
    fav.title = device.favorite ? '즐겨찾기 해제' : '즐겨찾기';
    fav.setAttribute('aria-label', fav.title);
    fav.addEventListener('click', function() { updateDevice(device.id, { favorite: !device.favorite }, true); });
    const menu = create('button', 'icon-action device-menu-trigger', '...');
    menu.type = 'button';
    menu.title = '기기 메뉴';
    menu.setAttribute('aria-label', '기기 메뉴');
    menu.addEventListener('click', function(event) { openDeviceMenu(event, device.id); });
    head.append(face, title, fav, menu);

    const status = create('div', 'device-status');
    status.append(create('strong', '', statusLabel(device)));
    const brand = brandLabel(device);
    if (brand) status.append(create('span', '', brand));

    const controls = create('div', 'device-controls');
    renderDeviceControls(controls, device);

    card.append(head, status, controls);
    grid.append(card);
  });
}
function renderDeviceControls(container, device) {
  if (device.type !== '센서') {
    const switchLabel = create('label', 'switch-line');
    const input = document.createElement('input');
    input.type = 'checkbox';
    input.checked = isPowerOn(device);
    input.addEventListener('change', function() {
      const patch = powerPatch(device, input.checked);
      void sendDeviceCommand(device, device.type === '도어락' ? 'lock' : 'power', input.checked, patch);
    });
    const slider = create('span', 'switch');
    const copy = create('span', '', device.type === '도어락' ? '잠금' : '전원');
    switchLabel.append(input, slider, copy);
    container.append(switchLabel);
  }
  if (device.type === '조명') {
    const wrap = create('label', 'range-control');
    const label = create('span', '', '밝기 ' + device.brightness + '%');
    const range = document.createElement('input');
    range.type = 'range';
    range.min = '1';
    range.max = '100';
    range.value = String(device.brightness);
    range.addEventListener('input', function() {
      label.textContent = '밝기 ' + range.value + '%';
      updateDevice(device.id, { brightness: Number(range.value), power: true, status: 'ON' }, false);
    });
    range.addEventListener('change', function() {
      void sendDeviceCommand(device, 'brightness', Number(range.value), { brightness: Number(range.value), power: true, status: 'ON' });
    });
    wrap.append(label, range);
    container.append(wrap);
    return;
  }
  if (device.type === '에어컨' || device.type === '난방') {
    const stepper = create('div', 'temp-stepper');
    const minus = create('button', 'btn icon-step', '-');
    const value = create('strong', '', String(device.targetTemp) + '℃');
    const plus = create('button', 'btn icon-step', '+');
    minus.type = 'button';
    plus.type = 'button';
    minus.title = '온도 내리기';
    plus.title = '온도 올리기';
    minus.addEventListener('click', function() {
      const nextTemp = Math.max(16, device.targetTemp - 1);
      void sendDeviceCommand(device, 'targetTemp', nextTemp, { targetTemp: nextTemp, power: true, status: 'ON' });
    });
    plus.addEventListener('click', function() {
      const nextTemp = Math.min(32, device.targetTemp + 1);
      void sendDeviceCommand(device, 'targetTemp', nextTemp, { targetTemp: nextTemp, power: true, status: 'ON' });
    });
    stepper.append(minus, value, plus);
    container.append(stepper);
    return;
  }
  if (device.type === '센서') {
    const readout = create('div', 'sensor-readout');
    readout.append(create('strong', '', formatValue(device)), create('span', '', batteryLabel(device)));
    container.append(readout);
    return;
  }
  if (device.type === '커튼') {
    const select = document.createElement('select');
    select.className = 'field';
    fillSelect(select, ['열림', '중간', '닫힘'], device.mode || '중간');
    select.addEventListener('change', function() { updateDevice(device.id, { mode: select.value, status: select.value === '닫힘' ? 'OFF' : 'ON', power: select.value !== '닫힘' }, true); });
    container.append(select);
    return;
  }
  if (device.battery != null) {
    container.append(create('span', 'battery-chip', batteryLabel(device)));
  }
}
function batteryLabel(device) {
  return device.battery == null ? '배터리 없음' : '배터리 ' + Math.round(Number(device.battery)) + '%';
}
function renderDetail() {
  const panel = document.getElementById('selected-device');
  panel.replaceChildren();
  const sideTitle = document.getElementById('side-title');
  if (sideTitle) sideTitle.textContent = activeSmartTab === 'devices' ? '선택 기기' : modeTitle();
  const device = selectedDevice();
  if (!device) {
    panel.append(create('div', 'empty compact-empty', '선택된 기기가 없습니다.'));
    return;
  }
  const meta = iconFor(device);
  const head = create('div', 'selected-head');
  head.append(create('div', 'device-face ' + meta.tone, meta.icon), create('div', '', ''));
  head.lastChild.append(create('strong', '', device.name), create('span', '', device.room + ' · ' + device.type));
  const grid = create('div', 'selected-grid');
  grid.append(
    detailPill('상태', statusLabel(device)),
    detailPill('연동', device.provider),
    detailPill('제조사', brandLabel(device) || '-'),
    detailPill('확인', formatTime(device.lastSeen))
  );
  if (device.battery != null) grid.append(detailPill('배터리', Math.round(Number(device.battery)) + '%'));
  if (device.type === '조명') grid.append(detailPill('밝기', device.brightness + '%'));
  if (device.type === '에어컨' || device.type === '난방') grid.append(detailPill('목표온도', device.targetTemp + '℃'));
  panel.append(head, grid);
}
function detailPill(label, value) {
  const node = create('div', 'detail-pill');
  node.append(create('span', '', label), create('strong', '', value));
  return node;
}
function addDevice() {
  const name = text(document.getElementById('new-device-name').value);
  if (!name) {
    setNotice('기기명을 입력하세요.', 'error');
    return;
  }
  const type = document.getElementById('new-device-type').value;
  const provider = document.getElementById('new-device-provider').value;
  const device = normalizeDevice({
    id: safeId('devices'),
    name: name,
    room: document.getElementById('new-device-room').value,
    type: type,
    provider: provider,
    brand: provider,
    status: type === '도어락' ? 'locked' : (type === '센서' ? 'ON' : 'OFF'),
    power: type === '센서' || type === '도어락',
    lastSeen: Date.now()
  }, devices.length);
  devices = devices.concat([device]);
  selectedId = device.id;
  document.getElementById('new-device-name').value = '';
  persist();
  render();
}
function applyScene(scene) {
  devices = devices.map(function(device, index) {
    const next = Object.assign({}, device);
    if (scene === 'away') {
      if (['조명', '플러그', '스피커', '에어컨', '난방'].includes(device.type)) Object.assign(next, { power: false, status: 'OFF' });
      if (device.type === '도어락') Object.assign(next, { power: true, status: 'locked' });
    }
    if (scene === 'home') {
      if (device.room === '거실' && ['조명', '플러그', '공기청정기'].includes(device.type)) Object.assign(next, { power: true, status: 'ON' });
    }
    if (scene === 'night') {
      if (device.type === '조명') Object.assign(next, { power: device.room === '침실', status: device.room === '침실' ? 'ON' : 'OFF', brightness: device.room === '침실' ? 20 : device.brightness });
      if (device.type === '도어락') Object.assign(next, { power: true, status: 'locked' });
    }
    if (scene === 'movie') {
      if (device.room === '거실' && device.type === '조명') Object.assign(next, { power: true, status: 'ON', brightness: 25 });
      if (device.room === '거실' && device.type === '스피커') Object.assign(next, { power: true, status: 'ON' });
    }
    next.lastSeen = Date.now();
    return normalizeDevice(next, index);
  });
  syncMessage = '장면 적용됨';
  lastSyncAt = Date.now();
  persist();
  render();
}
async function syncNow() {
  if (syncBusy) return;
  syncBusy = true;
  syncMessage = sourceProvider + ' 동기화';
  renderMetrics();
  try {
    const result = await requestSmartHome('smarthome.devices.sync', { provider: sourceProvider });
    integrationStatus = result && result.status ? result.status : integrationStatus;
    lastSyncAt = result && result.syncedAt ? result.syncedAt : Date.now();
    if (result && result.ok) {
      mergeSyncedDevices(sourceProvider, result.devices);
      syncMessage = sourceProvider + ' 동기화 완료';
      setNotice(sourceProvider + ' 기기 상태를 가져왔습니다.', 'ok');
    } else {
      syncMessage = sourceProvider + ' 설정 필요';
      setNotice(result && result.warnings && result.warnings[0] ? result.warnings[0] : sourceProvider + ' 동기화가 준비되지 않았습니다.', 'error');
    }
  } catch (error) {
    syncMessage = sourceProvider + ' 동기화 실패';
    setNotice(error instanceof Error ? error.message : String(error), 'error');
  } finally {
    syncBusy = false;
    persist();
    render();
  }
}
function render() {
  renderRibbonTabs();
  renderTabSummary();
  renderRoomTabs();
  renderMetrics();
  document.querySelector('.scene-strip').hidden = !(activeSmartTab === 'power' || activeSmartTab === 'devices');
  document.getElementById('room-tabs').hidden = activeSmartTab !== 'devices';
  document.querySelector('.add-device-band').hidden = activeSmartTab !== 'devices';
  renderCards();
  renderDetail();
}
fillSelect(document.getElementById('source-provider'), PROVIDERS, sourceProvider);
fillSelect(document.getElementById('provider-filter'), ['전체'].concat(PROVIDERS), activeProvider);
fillSelect(document.getElementById('new-device-room'), ROOMS, '거실');
fillSelect(document.getElementById('new-device-type'), TYPES, '조명');
fillSelect(document.getElementById('new-device-provider'), PROVIDERS, 'SmartThings');
document.getElementById('source-provider').addEventListener('change', function(event) {
  sourceProvider = event.target.value;
  syncMessage = sourceProvider + ' 선택됨';
  persist();
  renderMetrics();
});
document.getElementById('provider-filter').addEventListener('change', function(event) {
  activeProvider = event.target.value;
  persist();
  render();
});
document.getElementById('device-search').addEventListener('input', function(event) {
  searchQuery = event.target.value;
  render();
});
document.getElementById('add-device').addEventListener('click', addDevice);
document.getElementById('sync-now').addEventListener('click', syncNow);
document.querySelectorAll('[data-scene]').forEach(function(button) {
  button.addEventListener('click', function() { applyScene(button.dataset.scene); });
});
document.addEventListener('click', function(event) {
  const target = event.target;
  if (target && target.closest && (target.closest('#device-context-menu') || target.closest('.device-menu-trigger'))) return;
  closeDeviceMenu();
});
document.addEventListener('keydown', function(event) {
  if (event.key === 'Escape') closeDeviceMenu();
});
if (shouldPersist) persist();
render();
void loadIntegrationStatus(false);
`

