function fallbackBarRows(id, title, rows, formatter) {
  const plot = document.getElementById(id);
  if (!plot) return;
  plot.replaceChildren();
  plot.classList.add('fallback-plot');
  plot.append(make('h3', 'fallback-title', title));
  const list = make('div', 'fallback-bars');
  const max = Math.max(1, ...rows.map(function(row) { return Math.abs(number(row.value, 0)); }));
  rows.slice(0, 6).forEach(function(row) {
    const value = number(row.value, 0);
    const line = make('div', 'fallback-bar-row');
    const head = make('div', 'fallback-bar-head');
    head.append(make('span', '', row.label), make('strong', value >= 0 ? 'up' : 'down', formatter(value)));
    const track = make('div', 'fallback-track');
    const fill = make('span', value >= 0 ? 'up-bg' : 'down-bg');
    fill.style.width = Math.max(4, Math.min(100, (Math.abs(value) / max) * 100)) + '%';
    track.append(fill);
    line.append(head, track);
    list.append(line);
  });
  plot.append(list);
}
function fallbackTrend(id, title, points) {
  const plot = document.getElementById(id);
  if (!plot) return;
  plot.replaceChildren();
  plot.classList.add('fallback-plot');
  plot.append(make('h3', 'fallback-title', title));
  const values = points.map(function(point) { return number(point.value, 0); });
  const min = Math.min(...values);
  const max = Math.max(...values);
  const range = Math.max(1, max - min);
  const coords = values.map(function(value, index) {
    const x = values.length <= 1 ? 50 : (index / (values.length - 1)) * 100;
    const y = 42 - ((value - min) / range) * 34;
    return x.toFixed(1) + ',' + y.toFixed(1);
  }).join(' ');
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', '0 0 100 48');
  svg.setAttribute('class', 'fallback-spark');
  const polyline = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
  polyline.setAttribute('points', coords || '0,42 100,42');
  svg.append(polyline);
  plot.append(svg, make('p', 'fallback-note', points.length + '개 기록 · 현재 ' + money(values[values.length - 1] || 0)));
}
