  const timeline = buildPortfolioTimeline();
  const allocation = groupByCategory(items);
  const ranked = items.filter(function(item) { return !isLiability(item); }).sort(function(a, b) { return Math.abs(netValue(b)) - Math.abs(netValue(a)); }).slice(0, 9);
  const mapped = items.slice().sort(function(a, b) { return exposureValue(b) - exposureValue(a); }).slice(0, 9);
  const waterfall = [
    { label: '월 납입', value: totals(items).monthlyContribution },
    { label: '월 현금흐름', value: totals(items).monthlyIncome },
    { label: '대출', value: -totals(items).debt / 120 }
  ];
  if (primaryChartOpen()) fallbackTrend('chart-trend', '순자산 시계열', timeline);
  if (!secondaryChartsOpen()) return;
  fallbackBarRows('chart-allocation', '자산군 배분', Object.keys(allocation).map(function(key) { return { label: categoryLabel(key), value: allocation[key] }; }), money);
  fallbackBarRows('chart-return', '자산별 가격 변화율', ranked.map(function(item) { return { label: item.name, value: returnPct(item) }; }), pct);
  fallbackBarRows('chart-map', '보유 자산 맵', mapped.map(function(item) { return { label: item.name, value: exposureValue(item) }; }), money);
