  const zeroDefault = ['quantity', 'fxRate', 'ownershipShare', 'pensionStartAge', 'pensionEndAge', 'contributionEndAge'].includes(key) && number(node.value, 0) === 0;
  if (empty || zeroDefault) setFormValue(id, value);
