async function refreshQuotes(ids) {
  if (quoteBusy) return;
  const targets = items.filter(function(item) { return (!ids || ids.includes(item.id)) && eligibleForQuote(item); });
  if (targets.length === 0) {
    setStatus('시세코드가 있는 주식·연금·펀드·암호화폐 자산이 없습니다.', true);
    return;
  }
  quoteBusy = true;
  setStatus('Yahoo Finance Chart API로 시세를 조회 중입니다...', false);
  renderHoldingList();
  renderDetail();
  try {
    const result = await window.sepilotApps.request('market.quotes.fetch', {
      range: '6mo',
      interval: '1d',
      assets: targets.map(function(item) {
        return { id: item.id, name: item.name, symbol: item.symbol, market: item.market, type: item.type, currency: item.currency };
      })
    });
    const results = Array.isArray(result.results) ? result.results : [];
    let success = 0;
    items = items.map(function(item) {
      const quote = results.find(function(candidate) { return candidate.id === item.id; });
      if (!quote) return item;
      if (!quote.ok || !quote.price) {
        return Object.assign({}, item, { quoteStatus: quote.message || '시세 조회 실패', updatedAt: now() });
      }
      success += 1;
      const history = (quote.points || []).map(function(point) {
        return { ts: point.ts, date: point.date, price: point.close, source: quote.source || 'yahoo-finance-chart' };
      });
      quoteSeries.append({ ts: quote.asOf || now(), id: item.id, symbol: quote.requestSymbol || item.symbol, price: quote.price, currency: quote.currency || item.currency, source: quote.source || 'yahoo-finance-chart' });
      return Object.assign({}, item, {
        currentPrice: quote.price,
        currency: quote.currency || item.currency,
        history: history,
        lastQuoteAt: quote.asOf || now(),
        quoteStatus: 'Yahoo ' + (quote.requestSymbol || item.symbol),
        updatedAt: now()
      });
    });
    dashboardSeed.lastQuoteAt = result.checkedAt || now();
    dashboardSeed.lastProvider = result.provider || 'Yahoo Finance Chart API';
    persist({ snapshot: true });
    setStatus(success + '/' + targets.length + '개 자산 시세가 갱신되었습니다.', success === 0);
  } catch (error) {
    setStatus('시세 조회 실패: ' + (error && error.message ? error.message : String(error)), true);
  } finally {
    quoteBusy = false;
    render();
  }
}
