function entryRow(item) {
  const row = document.createElement('article');
  const external = isSubscriptionOwned(item);
  row.className = 'ledger-row ' + (item.type === '수입' ? 'income' : 'expense') + (external ? ' external-owned' : '');
  const date = inputField(item.date, 'date', '', function(event) { updateEntry(item.id, 'date', event.target.value); });
  const type = selectField(['수입', '지출'], item.type, function(event) { updateEntry(item.id, 'type', event.target.value); });
  const cat = document.createElement('select');
  cat.className = 'field';
  renderCategoryOptions(cat, item.type, item.type === '수입' ? incomeCategoryLabel(item) : expenseCategoryLabel(item));
  cat.addEventListener('change', function(event) { updateEntry(item.id, 'category', event.target.value); });
  const account = external ? inputField(SUBSCRIPTION_OWNER_TITLE, 'text', '소유 앱', function() {}) : document.createElement('select');
  if (!external) {
    account.className = 'field';
    renderAccountOptions(account, item.accountId);
    account.addEventListener('change', function(event) { updateEntry(item.id, 'accountId', event.target.value); });
  }
  const amount = inputField(item.amount, 'number', '금액', function(event) { updateEntry(item.id, 'amount', Number(event.target.value) || 0); });
  const memo = inputField(item.memo, 'text', '메모', function(event) { updateEntry(item.id, 'memo', event.target.value); });
  const memoCell = document.createElement('div');
  memoCell.className = 'ledger-memo-cell';
  memoCell.append(memo);
  if (external) memoCell.append(ownershipBadge(item));
  const remove = iconButton('×', 'danger', function() { removeEntry(item.id); });
  [date, type, cat, account, amount, memo, remove].forEach(function(control) {
    lockControl(control, item, control === remove ? '삭제' : '수정');
  });
  row.append(date, type, cat, account, amount, memoCell, remove);
  return row;
}
function updateEntry(id, key, value) {
  const current = entries.find(function(item) { return item.id === id; });
  if (isSubscriptionOwned(current) || String(id || '').indexOf(SUBSCRIPTION_OWNER_KIND + ':') === 0) return window.alert(readonlyHint({ sharedOriginTitle: SUBSCRIPTION_OWNER_TITLE }, '수정'));
  entries = entries.map(function(item) {
    if (item.id !== id) return item;
    const next = Object.assign({}, item, { [key]: value });
    if (key === 'type') next.category = catOptions(next.type, next.category).includes(next.category) ? next.category : catOptions(next.type, next.category)[0];
    return normalizeEntry(next) || item;
  });
  persist();
  render();
}
function removeEntry(id) {
  const current = entries.find(function(item) { return item.id === id; });
  if (isSubscriptionOwned(current) || String(id || '').indexOf(SUBSCRIPTION_OWNER_KIND + ':') === 0) return window.alert(readonlyHint({ sharedOriginTitle: SUBSCRIPTION_OWNER_TITLE }, '삭제'));
  entries = entries.filter(function(item) { return item.id !== id; });
  persist();
  render();
}
function updateAccount(id, key, value) {
  accounts = accounts.map(function(item) { return item.id === id ? Object.assign({}, item, { [key]: value }) : item; }).map(normalizeAccount).filter(Boolean);
  persist();
  render();
}
function removeAccount(id) {
  if (accounts.length <= 1) return;
  const fallback = accounts.find(function(item) { return item.id !== id; }).id;
  accounts = accounts.filter(function(item) { return item.id !== id; });
  entries = entries.map(function(item) { return item.accountId === id ? Object.assign({}, item, { accountId: fallback }) : item; });
  salaries = salaries.map(function(item) { return item.accountId === id ? Object.assign({}, item, { accountId: fallback }) : item; });
  persist();
  render();
}
function updateSalary(id, key, value) {
  salaries = salaries.map(function(item) { return item.id === id ? Object.assign({}, item, { [key]: value }) : item; }).map(normalizeSalary).filter(Boolean);
  persist();
  render();
}
function removeSalary(id) { salaries = salaries.filter(function(item) { return item.id !== id; }); persist(); render(); }
function updateBudget(id, key, value) {
  const current = budgets.find(function(item) { return item.id === id; });
  if (isSubscriptionOwned(current) || String(id || '').indexOf('budget-' + SUBSCRIPTION_OWNER_KIND + ':') === 0) return window.alert(readonlyHint({ sharedOriginTitle: SUBSCRIPTION_OWNER_TITLE }, '수정'));
  budgets = budgets.map(function(item) { return item.id === id ? Object.assign({}, item, { [key]: value }) : item; }).map(normalizeBudget).filter(Boolean);
  budgets = dedupeBudgets(budgets);
  persist();
  render();
}
function renameBudgetCategory(id, value) {
  const linked = budgets.find(function(item) { return item.id === id; });
  if (isSubscriptionOwned(linked) || String(id || '').indexOf('budget-' + SUBSCRIPTION_OWNER_KIND + ':') === 0) return window.alert(readonlyHint({ sharedOriginTitle: SUBSCRIPTION_OWNER_TITLE }, '수정'));
  const nextCategory = cleanText(value, '');
  if (!nextCategory) { render(); return; }
  const current = budgets.find(function(item) { return item.id === id; });
  if (!current) return;
  const previousCategory = current.category;
  const duplicate = budgets.find(function(item) { return item.id !== id && categoryKey(item.category) === categoryKey(nextCategory); });
  if (duplicate) {
    budgets = budgets.filter(function(item) { return item.id !== id; }).map(function(item) {
      return item.id === duplicate.id
        ? Object.assign({}, item, { category: nextCategory, limit: Number(current.limit) || Number(item.limit) || 0, memo: current.memo || item.memo })
        : item;
    });
  } else {
    budgets = budgets.map(function(item) { return item.id === id ? Object.assign({}, item, { category: nextCategory }) : item; });
  }
  entries = entries.map(function(item) {
    if (item.type !== '지출' || categoryKey(item.category) !== categoryKey(previousCategory)) return item;
    return Object.assign({}, item, { category: nextCategory });
  });
  budgets = dedupeBudgets(budgets);
  persist();
  render();
}
function removeBudget(id) {
  const current = budgets.find(function(item) { return item.id === id; });
  if (isSubscriptionOwned(current) || String(id || '').indexOf('budget-' + SUBSCRIPTION_OWNER_KIND + ':') === 0) return window.alert(readonlyHint({ sharedOriginTitle: SUBSCRIPTION_OWNER_TITLE }, '삭제'));
  budgets = budgets.filter(function(item) { return item.id !== id; });
  persist();
  render();
}
function addEntry() {
  const amount = Number(byId('entry-amount').value) || 0;
  if (!amount) return;
  entries = entries.concat([normalizeEntry({
    id: 'entries-' + Date.now(),
    date: byId('entry-date').value || toDateInput(today),
    type: byId('entry-type').value,
    category: byId('entry-category').value,
    accountId: byId('entry-account').value,
    amount: amount,
    memo: byId('entry-memo').value
  })]).filter(Boolean);
  byId('entry-amount').value = '';
  byId('entry-memo').value = '';
  persist();
  render();
}
function addBudget() {
  const category1 = cleanText(byId('budget-category1').value, '');
  const category2 = cleanText(byId('budget-category2').value, '');
  const category3 = cleanText(byId('budget-category3').value, '');
  if (!category1 && !category2 && !category3) return;
  const limit = Number(byId('budget-limit').value) || 0;
  const recurrence = normalizeBudgetRecurrence(byId('budget-recurrence').value);
  const recurrenceMonth = Math.min(12, Math.max(1, Number(byId('budget-recurrence-month').value) || monthNumber(selectedMonth)));
  const dueDay = Number(byId('budget-due-day').value) || 0;
  const paymentMethod = byId('budget-payment').value;
  const memo = byId('budget-memo').value;
  const category = categoryPath([category1, category2, category3]) || category2 || category1 || category3;
  const existing = budgets.find(function(item) {
    return categoryKey(expenseCategoryLabel(item) + '|' + item.recurrence + '|' + item.recurrenceMonth + '|' + item.dueDay + '|' + item.paymentMethod) === categoryKey(category + '|' + recurrence + '|' + recurrenceMonth + '|' + dueDay + '|' + paymentMethod);
  });
  if (existing) {
    budgets = budgets.map(function(item) {
      return item.id === existing.id ? Object.assign({}, item, { category, category1, category2, category3, limit, recurrence, recurrenceMonth, dueDay, paymentMethod, memo: memo || item.memo }) : item;
    });
  } else {
    budgets = budgets.concat([normalizeBudget({
      id: 'budget-' + Date.now(),
      category,
      category1,
      category2,
      category3,
      limit,
      recurrence,
      recurrenceMonth,
      dueDay,
      paymentMethod,
      memo
    })]).filter(Boolean);
  }
  budgets = dedupeBudgets(budgets);
  byId('budget-category1').value = '';
  byId('budget-category2').value = '';
  byId('budget-category3').value = '';
  byId('budget-limit').value = '';
  byId('budget-recurrence').value = 'variable';
  byId('budget-recurrence-month').value = '';
  byId('budget-due-day').value = '';
  byId('budget-payment').value = '';
  byId('budget-memo').value = '';
  persist();
  render();
}
