  setText('c-month', money(summary.monthCost));
  setText('c-fuel', money(summary.fuelCost));
  setText('c-efficiency', summary.avgFuelEfficiency ? fmtDecimal(summary.avgFuelEfficiency, 1) + ' km/L' : '계산 대기');
