function setActiveView(view) {
  if (!VIEW_LABELS[view]) return;
  activeView = view;
  data.set(['smartcar', 'activeView'], activeView);
  render();
}
function render() {
  renderMetrics();
  document.querySelectorAll('[data-car-view]').forEach(function(button) {
    const selected = button.dataset.carView === activeView;
    button.classList.toggle('active', selected);
    button.setAttribute('aria-selected', selected ? 'true' : 'false');
  });
  setText('view-title', VIEW_LABELS[activeView]);
  setText('view-subtitle', VIEW_DESCRIPTIONS[activeView]);
  const body = byId('car-view-body');
  body.replaceChildren();
  if (activeView === 'analysis') renderAnalysisView(body);
  else if (activeView === 'fuel') renderFuelView(body);
  else if (activeView === 'mileage') renderMileageView(body);
  else if (activeView === 'consumables') renderConsumablesView(body);
  else if (activeView === 'maintenance') renderMaintenanceView(body);
  else renderLogsView(body);
}
