function renderLinks() {
  var svg = document.getElementById('link-layer');
  var labelLayer = document.getElementById('link-label-layer');
  svg.replaceChildren();
  labelLayer.replaceChildren();
  visibleLinks().forEach(function(link) {
    var from = resolveNode(link.from);
    var to = resolveNode(link.to);
    if (!from || !to) return;
    var a = nodeCenter(from);
    var b = nodeCenter(to);
    var health = linkHealth(link);
    var hit = document.createElementNS(SVG_NS, 'line');
    hit.setAttribute('x1', String(a.x));
    hit.setAttribute('y1', String(a.y));
    hit.setAttribute('x2', String(b.x));
    hit.setAttribute('y2', String(b.y));
    hit.setAttribute('class', 'topology-link-hit');
    hit.dataset.linkId = link.id;
    hit.addEventListener('click', function(event) { event.stopPropagation(); setSelected('link', link.id); });
    hit.addEventListener('contextmenu', function(event) { openLinkMenu(event, link.id); });
    svg.append(hit);
    var line = document.createElementNS(SVG_NS, 'line');
    line.setAttribute('x1', String(a.x));
    line.setAttribute('y1', String(a.y));
    line.setAttribute('x2', String(b.x));
    line.setAttribute('y2', String(b.y));
    line.setAttribute('class', 'topology-link ' + health + (selected.kind === 'link' && selected.id === link.id ? ' selected' : ''));
    svg.append(line);
    var label = document.createElement('button');
    label.type = 'button';
    label.className = 'link-label ' + health + (selected.kind === 'link' && selected.id === link.id ? ' selected' : '');
    label.dataset.linkId = link.id;
    label.textContent = link.label || 'link';
    label.style.left = Math.round((a.x + b.x) / 2) + 'px';
    label.style.top = Math.round((a.y + b.y) / 2) + 'px';
    label.addEventListener('click', function(event) { event.stopPropagation(); setSelected('link', link.id); });
    label.addEventListener('contextmenu', function(event) { openLinkMenu(event, link.id); });
    labelLayer.append(label);
  });
  if (connectDraft) {
    var targetNode = connectDraft.toId ? nodes.find(function(node) { return node.id === connectDraft.toId; }) : null;
    var previewTo = targetNode ? nodeCenter(targetNode) : connectDraft.to;
    var preview = document.createElementNS(SVG_NS, 'line');
    preview.setAttribute('x1', String(connectDraft.from.x));
    preview.setAttribute('y1', String(connectDraft.from.y));
    preview.setAttribute('x2', String(previewTo.x));
    preview.setAttribute('y2', String(previewTo.y));
    preview.setAttribute('class', 'topology-link preview');
    svg.append(preview);
  }
}
